using UnityEditor;
using UnityEngine;
public static class PreviewLixinVfx {
  public static string Run() {
    Clear();
    float[] t = {0.2f, 0.7f, 0.25f, 0.28f};
    string[] keys = {"fx_lixin_gamble","fx_lixin_crunch","fx_lixin_overwork","fx_buff_atk"};
    var sb = new System.Text.StringBuilder();
    for (int i = 0; i < keys.Length; i++) {
      var prefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Bundle/Vfx/" + keys[i] + ".prefab");
      var go = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
      go.name = "PREVIEW_" + keys[i];
      go.hideFlags = HideFlags.DontSave;
      go.transform.position = new Vector3(i * 2.2f, 0f, 0f);
      var ps = go.GetComponent<ParticleSystem>();
      ps.Simulate(t[i], true, true);
      sb.Append(keys[i]).Append('=').Append(go.GetInstanceID()).Append(' ');
    }
    return sb.ToString().Trim();
  }
  public static string Clear() {
    var all = Object.FindObjectsByType<GameObject>(FindObjectsInactive.Include, FindObjectsSortMode.None);
    int n = 0;
    foreach (var go in all) {
      if (go != null && go.name.StartsWith("PREVIEW_fx_"))
      {
        Object.DestroyImmediate(go);
        n++;
      }
    }
    return "cleared " + n;
  }
}
